<?php require __DIR__.'/wordpress/wp-load.php';
update_option('home','http://localhost:8080');update_option('siteurl','http://localhost:8080');
$img=(int)get_posts(['post_type'=>'attachment','fields'=>'ids','numberposts'=>1])[0];
