$id=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'آزمون کارت‌های تصویری']);update_post_meta($id,'_elementor_edit_mode','builder');update_post_meta($id,'_elementor_template_type','wp-page');update_post_meta($id,'_elementor_version',ELEMENTOR_VERSION);update_post_meta($id,'_elementor_data',wp_slash(wp_json_encode([['id'=>'cardsroot','elType'=>'container','settings'=>['content_width'=>'full','flex_direction'=>'column'],'elements'=>$nodes]])));
$f=json_decode(file_get_contents(__DIR__.'/fixture.json'),true);$f['cards']=get_permalink($id);file_put_contents(__DIR__.'/fixture.json',wp_json_encode($f));Elementor\Plugin::instance()->files_manager->clear_cache();echo 'cards ready';
